func NewUpstreamValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (UpstreamValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing UpstreamValue Attribute Value",
				"While creating a UpstreamValue value, a missing attribute value was detected. "+
					"A UpstreamValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("UpstreamValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid UpstreamValue Attribute Type",
				"While creating a UpstreamValue value, an invalid attribute value was detected. "+
					"A UpstreamValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("UpstreamValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("UpstreamValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra UpstreamValue Attribute Value",
				"While creating a UpstreamValue value, an extra attribute value was detected. "+
					"A UpstreamValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra UpstreamValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewUpstreamValueUnknown(), diags
	}

	deletedAttribute, ok := attributes["deleted"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`deleted is missing from object`)

		return NewUpstreamValueUnknown(), diags
	}

	deletedVal, ok := deletedAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`deleted expected to be basetypes.BoolValue, was: %T`, deletedAttribute))
	}

	fullPathAttribute, ok := attributes["full_path"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`full_path is missing from object`)

		return NewUpstreamValueUnknown(), diags
	}

	fullPathVal, ok := fullPathAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`full_path expected to be basetypes.StringValue, was: %T`, fullPathAttribute))
	}

	repositoryIdAttribute, ok := attributes["repository_id"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`repository_id is missing from object`)

		return NewUpstreamValueUnknown(), diags
	}

	repositoryIdVal, ok := repositoryIdAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`repository_id expected to be basetypes.StringValue, was: %T`, repositoryIdAttribute))
	}

	visibleAttribute, ok := attributes["visible"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`visible is missing from object`)

		return NewUpstreamValueUnknown(), diags
	}

	visibleVal, ok := visibleAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`visible expected to be basetypes.BoolValue, was: %T`, visibleAttribute))
	}

	if diags.HasError() {
		return NewUpstreamValueUnknown(), diags
	}

	return UpstreamValue{
		Deleted:      deletedVal,
		FullPath:     fullPathVal,
		RepositoryId: repositoryIdVal,
		Visible:      visibleVal,
		state:        attr.ValueStateKnown,
	}, diags
}

func NewUpstreamValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) UpstreamValue {
	object, diags := NewUpstreamValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewUpstreamValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t UpstreamType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewUpstreamValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewUpstreamValueUnknown(), nil
	}

	if in.IsNull() {
		return NewUpstreamValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewUpstreamValueMust(UpstreamValue{}.AttributeTypes(ctx), attributes), nil
}

func (t UpstreamType) ValueType(ctx context.Context) attr.Value {
	return UpstreamValue{}
}

